use super::*;
use openbindings::{JsonValue,JsonLimits,NoVerdictReason,WorkControl};
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::Relaxed};
fn read(s:&str)->JsonValue{JsonValue::parse_with_limits(s,JsonLimits{max_depth:4096,..Default::default()}).unwrap()}
fn graph<'a>(c:&'a dyn WorkControl)->Graph<'a>{Graph::new(48<<20,None,64,c)}
fn pair(a:&str,b:&str,yes:bool){let(a,b)=(read(a),read(b));let c=AtomicBool::new(false);assert_eq!(equal(a.view(),b.view(),&mut graph(&c)).unwrap(),yes);assert_eq!(equal(b.view(),a.view(),&mut graph(&c)).unwrap(),yes);assert_eq!(literal_equal(a.view(),b.view(),&mut graph(&c)).unwrap(),yes);if yes{for _ in 0..3{let seed=RandomState::new();let mut pending=Vec::new();let x=fingerprint(a.view(),&seed,&mut pending,&mut graph(&c)).unwrap();assert!(pending.is_empty());let y=fingerprint(b.view(),&seed,&mut pending,&mut graph(&c)).unwrap();assert_eq!(x,y);assert!(pending.is_empty());}}}
struct Stop{n:AtomicUsize,at:usize}impl WorkControl for Stop{fn is_cancelled(&self)->bool{self.n.fetch_add(1,Relaxed)>=self.at}}
#[test]fn e01_e04_h01_exact_domains(){let kinds=["null","false","0",r#""""#,"[]","{}"];for(i,a)in kinds.iter().enumerate(){for(j,b)in kinds.iter().enumerate(){pair(a,b,i==j)}}for(a,b,e)in[("0","-0e999",true),("1","10e-1",true),("9007199254740992","9007199254740993",false),("1e400","10e399",true),("1e999999999999999999999","10e999999999999999999998",true),("9999999999999999999","99999999999999999990e-1",true),("100000000000000000001","100000000000000000002",false),(r#""a""#,r#""\u0061""#,true),(r#""😀""#,r#""\ud83d\ude00""#,true),(r#""\ud800""#,r#""\uD800""#,true),(r#""\ud800""#,r#""\\ud800""#,false),(r#""\ud800""#,r#""\udc00""#,false)]{pair(a,b,e)}}
#[test]fn e05_long_chunked_units_and_names(){for n in [1023,1024,1025,65536]{let a=format!(r#""{}""#,"a".repeat(n));let b=format!(r#""{}""#,r"\u0061".repeat(n));let late=format!(r#""{}b""#,"a".repeat(n-1));pair(&a,&b,true);pair(&a,&late,false);let x=format!("{{{a}:1}}");let y=format!("{{{b}:1.0}}");pair(&x,&y,true);}}
#[test]fn e06_e09_iterative_shapes(){for(a,b,e)in[("[1,2]","[2,1]",false),("[]","[]",true),(r#"{"a":1,"b":[{},[]]}"#,r#"{"b":[{},[]],"\u0061":1.0}"#,true),(r#"{"a":1,"b":2}"#,r#"{"a":2,"b":1}"#,false),(r#"{"\ud800":{"😀":null}}"#,r#"{"\uD800":{"\ud83d\ude00":null}}"#,true)]{pair(a,b,e)}for n in [64,256,1024]{let a=format!("{}0{}","[".repeat(n),"]".repeat(n));let b=format!("{}0.0{}","[".repeat(n),"]".repeat(n));pair(&a,&b,true)}let a=format!("[{}]",(0..20000).map(|n|n.to_string()).collect::<Vec<_>>().join(","));let mut b=a.clone();b.replace_range(b.len()-6..b.len()-1,"20000");pair(&a,&a,true);pair(&a,&b,false);}
#[test]fn d02_d03_duplicate_subtree_defense(){let left=read(r#"{"a":1,"b":1}"#);let data=read(r#"{"bad":{"a":1,"\u0061":1},"good":{"b":1.0,"a":1},"other":[{"x":1,"x":1}]}"#);let c=AtomicBool::new(false);assert!(literal_equal(left.view(),data.get("good").unwrap(),&mut graph(&c)).unwrap());assert!(!literal_equal(left.view(),data.get("bad").unwrap(),&mut graph(&c)).unwrap());let a=read(r#"[{"x":1}]"#);assert!(!literal_equal(a.view(),data.get("other").unwrap(),&mut graph(&c)).unwrap());}
#[test]fn l01_l04_real_index_and_hash_cancellation(){for n in [15,16,17,100]{let mut f=(0..n-3).map(|i|format!(r#""k{i}":{i}"#)).collect::<Vec<_>>();f.extend([r#""\ud800":1000"#.into(),r#""😀":1001"#.into(),r#""long":1002"#.into()]);let a=format!("{{{}}}",f.join(","));f.reverse();let b=format!("{{{}}}",f.join(",")).replace(r#""k2""#,r#""k\u0032""#);pair(&a,&b,true);let object=read(&a);let absent=read(r#""not present""#);let c=AtomicBool::new(false);let mut g=graph(&c);let matches=backend::member_candidates(object.view(),absent.view(),|n|g.work(n)).unwrap().filter(|m|m.name.as_string()==absent.view().as_string()).count();assert_eq!(matches,0);}
let name="a".repeat(65536);let mut f=(0..15).map(|i|format!(r#""k{i}":{i}"#)).collect::<Vec<_>>();f.push(format!(r#""{name}":42"#));let object=read(&format!("{{{}}}",f.join(",")));let name=read(&format!(r#""{name}""#));let all=Stop{n:AtomicUsize::new(0),at:usize::MAX};let mut g=graph(&all);let v=backend::member_candidates(object.view(),name.view(),|n|g.work(n)).unwrap();assert_eq!(v.count(),1);let count=all.n.load(Relaxed);assert!(count>64);for at in 0..count{let c=Stop{n:AtomicUsize::new(0),at};let mut g=graph(&c);assert_eq!(backend::member_candidates(object.view(),name.view(),|n|g.work(n)).unwrap_err().reason,NoVerdictReason::Cancelled);}println!("name-hash-checkpoints={count}");}
#[test]fn h02_h05_collisions_and_early_duplicate(){let c=AtomicBool::new(false);for(s,yes)in[("[0,1,2]",true),("[0,1,0]",false),(r#"[{"x":0},{"x":1},{"x":0.0}]"#,false),(r#"[{"x":0},{"x":1},{"x":2}]"#,true),(r#"[{"a":1,"b":2},{"b":1,"a":2}]"#,true)]{let v=read(s);let candidates=(0..v.view().len().unwrap()).map(|i|(0,i)).collect::<Vec<_>>();assert_eq!(verify_candidates(v.view(),&candidates,&mut graph(&c)).unwrap(),yes);assert_eq!(unique(v.view(),&mut graph(&c)).unwrap(),yes);}let equal=read(&format!("[{}]",vec!["0";20000].join(",")));let candidates=(0..20000).map(|i|(0,i)).collect::<Vec<_>>();assert!(!verify_candidates(equal.view(),&candidates,&mut Graph::new(0,Some(100),64,&c)).unwrap());let distinct=read(&format!("[{}]",(0..100).map(|i|i.to_string()).collect::<Vec<_>>().join(",")));let candidates=(0..100).map(|i|(0,i)).collect::<Vec<_>>();assert_eq!(verify_candidates(distinct.view(),&candidates,&mut Graph::new(1<<20,Some(100),64,&c)).unwrap_err().reason,NoVerdictReason::LimitExceeded);}
#[test]fn h06_h07_hash_scratch_and_vacuous(){let c=AtomicBool::new(false);let seed=RandomState::new();let deep=read(&format!("{}0{}","[".repeat(256),"]".repeat(256)));let scalar=read("1");let mut pending=Vec::new();fingerprint(deep.view(),&seed,&mut pending,&mut graph(&c)).unwrap();assert!(pending.is_empty());let snap=crate::review_allocations::start();for _ in 0..1000{fingerprint(scalar.view(),&seed,&mut pending,&mut graph(&c)).unwrap();assert!(pending.is_empty());}let m=crate::review_allocations::finish(snap,1000);assert_eq!(m["allocations_per_op"],0.0);for text in["[]","[{}]"]{assert!(unique(read(text).view(),&mut Graph::new(0,Some(1),64,&c)).unwrap());}println!("warm-hash={m}");}
#[test]fn s01_s02_c01_all_stops_owner_release_and_exact_limits(){let a=read(r#"[{"a":[1,2]},{"a":[1,3]},{"b":"\ud800"}]"#);let b=read(r#"[{"a":[1.0,2]},{"a":[1,3.0]},{"b":"\uD800"}]"#);let available=AtomicBool::new(false);
for kind in [0,1,2]{let call=|g:&mut Graph<'_>|->Result<bool,NoVerdict>{match kind{0=>literal_equal(a.view(),b.view(),g),1=>unique(a.view(),g),_=>{let candidates=[(0,0),(0,1),(0,2)];verify_candidates(a.view(),&candidates,g)}}};let all=Stop{n:AtomicUsize::new(0),at:usize::MAX};let mut g=Graph::new(48<<20,Some(usize::MAX),64,&all);assert!(call(&mut g).unwrap());let checks=all.n.load(Relaxed);let bytes=(48<<20)-g.remaining().bytes;let work=usize::MAX-g.remaining().work.unwrap();for at in 0..checks{let stop=Stop{n:AtomicUsize::new(0),at};let snap=crate::review_allocations::start();let e=call(&mut graph(&stop)).unwrap_err();assert_eq!(e.reason,NoVerdictReason::Cancelled);drop(e);let m=crate::review_allocations::finish(snap,1);assert_eq!(m["ending_live_bytes"],m["baseline_live_bytes"]);assert!(call(&mut graph(&available)).unwrap());}for n in [0,bytes-1,bytes]{let r=call(&mut Graph::new(n,None,64,&available));assert_eq!(r.is_ok(),n==bytes);}for n in [0,work-1,work]{let r=call(&mut Graph::new(48<<20,Some(n),64,&available));assert_eq!(r.is_ok(),n==work);}println!("kind={kind} checks={checks} bytes={bytes} work={work}");}
}
#[test]fn e09_release_small_stack(){std::thread::Builder::new().stack_size(128<<10).spawn(||{let a=format!("{}0{}","[".repeat(1024),"]".repeat(1024));pair(&a,&a,true);}).unwrap().join().unwrap();}
